"""工作区文件浏览 API — 支持多根目录浏览。

根目录从 config.workspace_dirs 获取，默认包含：
~/workspace, ~, ~/documents, /home/company/shared, ~/tmp
"""
import os
import shutil
from pathlib import Path

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel

router = APIRouter(prefix='/workspace', tags=['workspace'])

# 禁止浏览的敏感文件扩展名 / 文件名
_BLOCKED_NAMES = {'agent.db', 'agent.pid', 'config.yaml', 'config.json'}
_BLOCKED_EXTS = {'.db', '.sqlite', '.sqlite3', '.pid', '.log'}


def _get_config():
    """获取 RuntimeConfig。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        raise HTTPException(status_code=500, detail='Agent 未初始化')
    return app.config


def _get_root_dir(root_index: int) -> Path:
    """根据索引获取根目录。"""
    config = _get_config()
    roots = config.workspace_dirs
    if root_index < 0 or root_index >= len(roots):
        raise HTTPException(status_code=404, detail='根目录不存在')
    return Path(roots[root_index]['path']).resolve()


def _safe_resolve(root_dir: Path, rel_path: str) -> Path:
    """安全解析相对路径，确保不超出根目录范围。"""
    if not rel_path:
        return root_dir
    target = (root_dir / rel_path).resolve()
    if not str(target).startswith(str(root_dir)):
        raise HTTPException(status_code=403, detail='路径越界：不允许访问工作区外的文件')
    return target


@router.get('/roots')
async def get_roots():
    """返回配置的工作区根目录列表。"""
    config = _get_config()
    result = []
    for wd in config.workspace_dirs:
        p = Path(wd['path'])
        result.append({
            'label': wd['label'],
            'path': str(p),
            'exists': p.exists() and p.is_dir(),
        })
    return result


@router.get('/files')
async def list_files(
    root: int = Query(0, description='根目录索引（workspace_dirs 数组下标）'),
    path: str = Query('', description='相对于根目录的子目录路径'),
):
    """列出指定根目录下的内容。"""
    root_dir = _get_root_dir(root)
    target = _safe_resolve(root_dir, path)

    if not target.exists():
        raise HTTPException(status_code=404, detail='目录不存在')
    if not target.is_dir():
        raise HTTPException(status_code=400, detail='路径不是目录')

    items = []
    try:
        entries = sorted(target.iterdir(), key=lambda p: (not p.is_dir(), p.name.lower()))
    except PermissionError:
        raise HTTPException(status_code=403, detail='无权限访问该目录')

    for entry in entries:
        # 跳过隐藏文件（以 . 开头）
        if entry.name.startswith('.'):
            continue
        try:
            stat = entry.stat()
            items.append({
                'name': entry.name,
                'path': str(entry.relative_to(root_dir)),
                'is_dir': entry.is_dir(),
                'size': stat.st_size if not entry.is_dir() else 0,
                'modified': os.path.getmtime(entry),
            })
        except (PermissionError, OSError):
            continue

    return {
        'root': root,
        'path': path or '',
        'absolute_path': str(target),
        'items': items,
    }


@router.get('/files/content')
async def read_file_content(
    path: str = Query(..., description='相对于根目录的文件路径'),
    root: int = Query(0, description='根目录索引'),
    max_size: int = Query(1_048_576, description='最大读取字节数（默认 1MB）'),
):
    """读取指定根目录下的文件内容（文本模式）。"""
    root_dir = _get_root_dir(root)
    target = _safe_resolve(root_dir, path)

    if not target.exists():
        raise HTTPException(status_code=404, detail='文件不存在')
    if target.is_dir():
        raise HTTPException(status_code=400, detail='路径是目录，不是文件')

    # 安全检查
    if target.name in _BLOCKED_NAMES or target.suffix.lower() in _BLOCKED_EXTS:
        raise HTTPException(status_code=403, detail='不允许访问该文件类型')

    try:
        file_size = target.stat().st_size
    except OSError:
        raise HTTPException(status_code=500, detail='无法读取文件信息')

    if file_size > max_size:
        return {
            'path': path,
            'content': None,
            'size': file_size,
            'truncated': True,
            'message': f'文件过大（{file_size} 字节），超过限制 {max_size} 字节',
        }

    try:
        content = target.read_text(encoding='utf-8', errors='replace')
    except Exception as e:
        raise HTTPException(status_code=500, detail=f'读取文件失败: {e}')

    return {
        'path': path,
        'content': content,
        'size': file_size,
        'truncated': False,
    }


# ─────────────────────────────────────────
# 文件操作 API
# ─────────────────────────────────────────

class CreateFileRequest(BaseModel):
    root: int
    path: str = ''
    name: str
    is_dir: bool = False


class RenameFileRequest(BaseModel):
    root: int
    path: str
    new_name: str


class WriteFileRequest(BaseModel):
    root: int
    path: str
    content: str


@router.post('/files')
async def create_file_or_folder(req: CreateFileRequest):
    """创建文件或文件夹。"""
    root_dir = _get_root_dir(req.root)
    parent = _safe_resolve(root_dir, req.path)

    if not parent.exists() or not parent.is_dir():
        raise HTTPException(status_code=404, detail='父目录不存在')

    target = parent / req.name
    if target.exists():
        raise HTTPException(status_code=409, detail='同名文件或文件夹已存在')

    try:
        if req.is_dir:
            target.mkdir(parents=True, exist_ok=True)
        else:
            target.write_text('', encoding='utf-8')
    except Exception as e:
        raise HTTPException(status_code=500, detail='创建失败: %s' % e)

    return {'ok': True, 'path': str(target.relative_to(root_dir))}


@router.delete('/files')
async def delete_file_or_folder(
    root: int = Query(...),
    path: str = Query(...),
):
    """删除文件或文件夹。"""
    root_dir = _get_root_dir(root)
    target = _safe_resolve(root_dir, path)

    if not target.exists():
        raise HTTPException(status_code=404, detail='文件或文件夹不存在')

    # 不允许删除根目录本身
    if target == root_dir:
        raise HTTPException(status_code=403, detail='不允许删除根目录')

    try:
        if target.is_dir():
            shutil.rmtree(target)
        else:
            target.unlink()
    except Exception as e:
        raise HTTPException(status_code=500, detail='删除失败: %s' % e)

    return {'ok': True}


@router.put('/files/rename')
async def rename_file_or_folder(req: RenameFileRequest):
    """重命名文件或文件夹。"""
    root_dir = _get_root_dir(req.root)
    target = _safe_resolve(root_dir, req.path)

    if not target.exists():
        raise HTTPException(status_code=404, detail='文件或文件夹不存在')

    new_target = target.parent / req.new_name
    if new_target.exists():
        raise HTTPException(status_code=409, detail='同名文件或文件夹已存在')

    try:
        target.rename(new_target)
    except Exception as e:
        raise HTTPException(status_code=500, detail='重命名失败: %s' % e)

    return {'ok': True, 'new_path': str(new_target.relative_to(root_dir))}


@router.put('/files/content')
async def write_file_content(req: WriteFileRequest):
    """写入文件内容。"""
    root_dir = _get_root_dir(req.root)
    target = _safe_resolve(root_dir, req.path)

    if target.is_dir():
        raise HTTPException(status_code=400, detail='路径是目录，不是文件')

    if target.name in _BLOCKED_NAMES or target.suffix.lower() in _BLOCKED_EXTS:
        raise HTTPException(status_code=403, detail='不允许写入该文件类型')

    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(req.content, encoding='utf-8')
    except Exception as e:
        raise HTTPException(status_code=500, detail='写入失败: %s' % e)

    return {'ok': True}
